import ExcelJS from 'exceljs';

/**
 * 导出数据
 * @param dataList
 * @param columnObjects
 */
export var exportData = function exportData(dataList, columnObjects, downloadName) {
  // 获取 roomAcXlsx 的键顺序
  var headerKeys = Object.keys(columnObjects);
  // 过滤数据，只保留 roomAcXlsx 中存在的字段，并按照 roomAcXlsx 的顺序排列
  var filteredData = dataList.map(function (item) {
    var filteredItem = {};
    headerKeys.forEach(function (key) {
      if (item.hasOwnProperty(key)) {
        filteredItem[key] = item[key];
      }
    });
    return filteredItem;
  });
  // 创建工作簿和工作表
  var workbook = new ExcelJS.Workbook();
  var worksheet = workbook.addWorksheet('Sheet1');
  // 添加表头
  var headers = headerKeys.map(function (key) {
    return columnObjects[key];
  });
  worksheet.addRow(headers);
  // 添加数据行
  filteredData.forEach(function (row) {
    worksheet.addRow(Object.values(row));
  });
  // 设置表头样式
  var headerRow = worksheet.getRow(1);
  headerRow.eachCell(function (cell) {
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: {
        argb: 'FFDDDDDD'
      }
    };
    cell.font = {
      bold: true,
      color: {
        argb: 'FF000000'
      }
    };
    cell.border = {
      top: {
        style: 'thin'
      },
      left: {
        style: 'thin'
      },
      bottom: {
        style: 'thin'
      },
      right: {
        style: 'thin'
      }
    };
    cell.alignment = {
      horizontal: 'center',
      vertical: 'middle'
    };
  });

  // 设置数据行样式
  worksheet.eachRow(function (row, rowNumber) {
    if (rowNumber > 1) {
      // 跳过表头行
      row.eachCell(function (cell) {
        cell.border = {
          top: {
            style: 'thin'
          },
          left: {
            style: 'thin'
          },
          bottom: {
            style: 'thin'
          },
          right: {
            style: 'thin'
          }
        };
        cell.alignment = {
          horizontal: 'center',
          vertical: 'middle'
        };
      });
    }
  });
  // 自动调整列宽
  worksheet.columns.forEach(function (column) {
    var maxLength = 0;
    var MAX_COLUMN_WIDTH = 30; // 设置最大列宽为30（可根据需要调整）
    column.eachCell(function (cell) {
      var columnLength = cell.value ? cell.value.toString().length : 10;
      if (columnLength > maxLength) {
        maxLength = columnLength;
      }
    });
    column.width = maxLength < 10 ? 10 : MAX_COLUMN_WIDTH;
  });
  // 导出文件
  workbook.xlsx.writeBuffer().then(function (buffer) {
    var blob = new Blob([buffer], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    });
    var url = window.URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    // 设置文件名
    a.download = downloadName + '.xlsx';
    a.click();
    window.URL.revokeObjectURL(url);
  });
};

