export var submitUpload = function submitUpload(fileList, columnObjects) {
  var promises = fileList.map(function (file) {
    return new Promise(function (resolve, reject) {
      var reader = new FileReader();
      reader.onload = function (e) {
        var data = new Uint8Array(e.target.result);
        var workbook = new ExcelJS.Workbook();
        workbook.xlsx.load(data).then(function () {
          var worksheet = workbook.getWorksheet(1);
          var rows = worksheet._rows;
          // 获取表头
          var headers = rows[0].values;
          var info = [];
          var _loop = function _loop() {
            var row = rows[i];
            // 跳过无效行
            if (!row || !row.values) return 1; // continue
            var rowData = {};
            headers.forEach(function (header, index) {
              // 使用映射关系转换属性名
              rowData[columnObjects[header] || header] = row.values[index] || '';
            });
            info.push(rowData);
          };
          for (var i = 1; i < rows.length; i++) {
            if (_loop()) continue;
          }
          resolve(info);
        }).catch(reject);
      };
      reader.onerror = reject;
